+  content: string;
+  revision?: string;
+  etag?: string;
+}
+
+export interface NoteVaultCapabilities {
+  watch?: boolean;
+  trash?: boolean;
+  renameFile?: boolean;
+  renameFolder?: boolean;
+  createFile?: boolean;
+  createFolder?: boolean;
+  deleteFile?: boolean;
+  deleteFolder?: boolean;
+  optimisticWrites?: boolean;
+  offline?: boolean;
+}
+
+export interface NoteVaultListOptions {
